def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(bid)

    if not alive_opponents:
        return max(0.0, min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 120.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 120.0
    max_urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else max_prev

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0.0:
        tightness = 0.0
    if tightness > 1.0:
        tightness = 1.0

    survival_mode = hp <= 3 or no_water_days >= 1
    danger_mode = hp <= 2 or no_water_days >= 2

    if supply >= 23:
        base = 38.0
    elif supply >= 20:
        base = 62.0
    elif supply >= 18:
        base = 92.0
    else:
        base = 122.0

    target = base

    if supply <= 18:
        target = max(target, max_prev + 2.5)
    elif supply <= 20:
        target = max(target, avg_prev + 1.5)
    else:
        target = max(target, avg_prev * 0.72)

    if survival_mode:
        target = max(target, max_urgent_prev + 3.0, 118.0)
    if danger_mode:
        target = max(target, max_prev + 6.0, 145.0)

    if hp >= 7 and no_water_days == 0 and supply >= 21:
        target *= 0.82

    if day >= 8 and budget > DAILY_SALARY * 3:
        target *= 1.06

    reserve_floor = DAILY_SALARY * max(1, 10 - int(day)) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if danger_mode:
        max_affordable = budget
    elif survival_mode:
        max_affordable = max(max_affordable, budget * 0.72)

    bid = min(target, max_affordable)
    bid = min(bid, budget)
    if bid < 0.0:
        bid = 0.0

    if budget < 45.0 and not survival_mode:
        bid = min(bid, max(12.0, budget * 0.55))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, max(1, DAILY_SALARY * 0.5))

    # Collect yesterday's bids from previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Estimate current opponent aggressiveness
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        mean_prev = sum(yesterday_bids) / len(yesterday_bids)
        # If max is very high, opponents are aggressive; we can be conservative if hp is good
        if max_prev > DAILY_SALARY * 1.2:
            if hp > 5:
                target = max(1, mean_prev * 0.7)
            elif hp <= 2:
                target = min(budget, max(DAILY_SALARY * 0.9, max_prev * 0.85))
            else:
                target = min(budget, max(DAILY_SALARY * 0.6, mean_prev * 0.8))
        else:
            # Moderate aggressiveness - bid slightly above average
            target = min(budget, max(DAILY_SALARY * 0.5, mean_prev * 0.9))
    else:
        # No info: use fixed strategy based on hp
        if hp <= 2:
            target = min(budget, DAILY_SALARY * 0.85)
        elif hp <= 5:
            target = min(budget, DAILY_SALARY * 0.65)
        else:
            target = min(budget, DAILY_SALARY * 0.55)

    # Ensure bid non-negative, not exceed budget
    bid = max(0, min(budget, target))
    return bid
